use serde::{Deserialize,Serialize};use tauri::{AppHandle,Manager,State};use crate::{app_state::AppState,errors::BackendError,models::{import_v2::{ImportInput,ImportInputKind,ImportSession},import_v2_web::AddImportUrlV2Request},services::import_v2::{connector_session::ConnectorSessionRef,url_policy::{PrivateTargetGrant,UrlPolicy}}};
#[derive(Debug,Serialize,Deserialize)]#[serde(rename_all="camelCase")]pub struct LoginRequest{pub platform:String}
#[derive(Debug,Serialize,Deserialize)]#[serde(rename_all="camelCase")]pub struct RevokeRequest{pub session_id:String}
#[derive(Debug,Serialize,Deserialize)]#[serde(rename_all="camelCase")]pub struct AuthorizePrivateTargetRequest{pub item_id:String,pub url:String}
#[tauri::command]pub fn add_import_url_v2(state:State<'_,AppState>,request:AddImportUrlV2Request)->Result<ImportSession,BackendError>{let context=state.resolve_project_context(&request.project_id,&request.project_root_path)?;let target=UrlPolicy.normalize_for_session(&request.url)?;state.import_v2_service.add_inputs(&context,&state.file_store,&request.session_id,vec![ImportInput{kind:ImportInputKind::Url,display_name:target.public.host.clone(),locator:target.public.public_url.clone(),normalized_locator:Some(target.public.public_url),source_identity:None}])}
#[tauri::command]pub fn begin_import_login_v2(app:AppHandle,state:State<'_,AppState>,request:LoginRequest)->Result<ConnectorSessionRef,BackendError>{let root=app.path().app_data_dir().map_err(|_|BackendError::new("IMPORT_V2_BROWSER_SESSION_FAILED","App data path is unavailable.",true,true))?.join("connector-profiles");state.connector_session_service.create(&request.platform,&root)}
#[tauri::command]pub fn revoke_import_login_v2(state:State<'_,AppState>,request:RevokeRequest)->Result<(),BackendError>{state.connector_session_service.revoke(&request.session_id)}
#[tauri::command]pub async fn authorize_import_private_target_v2(state:State<'_,AppState>,request:AuthorizePrivateTargetRequest)->Result<String,BackendError>{let target=UrlPolicy.normalize_for_session(&request.url)?;let port=target.request_url.port_or_known_default().ok_or_else(||BackendError::new("IMPORT_V2_URL_REJECTED","URL port is invalid.",false,true))?;let ips=tokio::net::lookup_host((target.public.host.as_str(),port)).await.map_err(|_|BackendError::new("IMPORT_V2_DNS_FAILED","DNS resolution failed.",true,true))?.map(|a|a.ip()).collect();let grant=PrivateTargetGrant{item_id:request.item_id,scheme:target.public.scheme,host:target.public.host,port,resolved_ips:ips,expires_at:chrono::Utc::now()+chrono::Duration::minutes(5)};state.connector_session_service.authorize_private(grant)}
